import React, { useRef } from 'react';
import { FileUpload } from 'primereact/fileupload';
import { Toast } from 'primereact/toast';

export default function Auto() {
    const toast = useRef(null);

    const onUpload = (event) => {
        toast.current.show({ 
            severity: 'success', 
            summary: 'Success', 
            detail: event.files.length > 0 ? `${event.files.length} file(s) uploaded` : 'No file uploaded',
            life: 3000 
        });
    };
        
    return (
        <>
            <Toast ref={toast} />
            <FileUpload mode="basic" name="demo[]" url="/api/upload" accept="image/*" maxFileSize={1000000} onUpload={onUpload} auto chooseLabel="Browse" />
        </>  
    )

}